-- Read-only capture from live World 1 2026-11-24, not player data.
-- Actual A319-100 configuration 16 and actual BEG->ZAG / BEG->MUC
-- 4-week Saturday 11:00 local route-game restriction SCREEN, using
-- the exact game phase-profile reference flight duration, not an invented
-- itinerary duration. This is a point-in-time source fixture: authoritative
-- releases, real slot issuer, pilot licences and maintenance not cloned.
-- The function under test is loaded byte-for-byte from server/sql.
\set ON_ERROR_STOP on
DO $safe$ BEGIN IF current_database()<>'airlinerra_disposable' OR current_user<>'postgres' THEN RAISE EXCEPTION 'SOURCE_EVIDENCE_DISPOSABLE_ONLY';END IF;END $safe$;
CREATE TABLE airlinerra_game.fixture_source_route_game_evidence (
 destination_code text PRIMARY KEY,destination_airport_key text NOT NULL,
 phase_profile jsonb NOT NULL,weekly_screen jsonb NOT NULL,
 source_kind text NOT NULL DEFAULT 'READ_ONLY_LIVE_WORLD1_2026_11_24',
 CHECK (jsonb_typeof(weekly_screen->'occurrences')='array')
);
